-- Primebrick: trigger-filter-hint-user — rewrites the `filter` field hint
-- of job_trigger from a dev-cut mechanic ("JSON conditions … array of
-- `{field, op, value}`") into a user-cut purpose statement: WHAT the filter
-- is for (restrict which events run the job) and WHAT empty means (react
-- to every event). No wire/schema vocabulary.

UPDATE job.translations SET value = 'Restrict which events fire this trigger — the job runs only when every added condition matches the event''s data. Leave empty to react to every event.', updated_at = now(), updated_by = 'migration-trigger-filter-hint', version = version + 1 WHERE key = 'job.entities.job_trigger.hints.filter' AND language = 'en-GB' AND deleted_at IS NULL;
UPDATE job.translations SET value = 'Restrict which events fire this trigger — the job runs only when every added condition matches the event''s data. Leave empty to react to every event.', updated_at = now(), updated_by = 'migration-trigger-filter-hint', version = version + 1 WHERE key = 'job.entities.job_trigger.hints.filter' AND language = 'en-US' AND deleted_at IS NULL;
UPDATE job.translations SET value = 'Restringe gli eventi che attivano questo attivatore — il job viene eseguito solo quando tutte le condizioni aggiunte corrispondono ai dati dell''evento. Lascia vuoto per reagire a ogni evento.', updated_at = now(), updated_by = 'migration-trigger-filter-hint', version = version + 1 WHERE key = 'job.entities.job_trigger.hints.filter' AND language = 'it-IT' AND deleted_at IS NULL;
UPDATE job.translations SET value = 'Schränkt ein, welche Ereignisse diesen Trigger auslösen — der Job läuft nur, wenn alle hinzugefügten Bedingungen auf die Ereignisdaten zutreffen. Leer lassen, um auf jedes Ereignis zu reagieren.', updated_at = now(), updated_by = 'migration-trigger-filter-hint', version = version + 1 WHERE key = 'job.entities.job_trigger.hints.filter' AND language = 'de-DE' AND deleted_at IS NULL;
UPDATE job.translations SET value = 'Restreint les événements qui déclenchent ce déclencheur — le job s''exécute uniquement lorsque toutes les conditions ajoutées correspondent aux données de l''événement. Laisser vide pour réagir à chaque événement.', updated_at = now(), updated_by = 'migration-trigger-filter-hint', version = version + 1 WHERE key = 'job.entities.job_trigger.hints.filter' AND language = 'fr-FR' AND deleted_at IS NULL;
UPDATE job.translations SET value = 'Restringe qué eventos disparan este trigger — el job se ejecuta solo cuando todas las condiciones añadidas coinciden con los datos del evento. Dejar vacío para reaccionar a cada evento.', updated_at = now(), updated_by = 'migration-trigger-filter-hint', version = version + 1 WHERE key = 'job.entities.job_trigger.hints.filter' AND language = 'es-ES' AND deleted_at IS NULL;
UPDATE job.translations SET value = 'Restringe que eventos disparam este trigger — o job é executado apenas quando todas as condições adicionadas correspondem aos dados do evento. Deixar vazio para reagir a cada evento.', updated_at = now(), updated_by = 'migration-trigger-filter-hint', version = version + 1 WHERE key = 'job.entities.job_trigger.hints.filter' AND language = 'pt-PT' AND deleted_at IS NULL;
